code_templates.solution_code:
package main

import "fmt"

type BankAccount struct {
	holder  string
	balance int
}

func main() {
	acc := BankAccount{"pythontip", 100000}
	var amount int
	fmt.Scanln(&amount)
	acc.withdraw(amount)
	fmt.Println(acc)
}
func (pt *BankAccount) withdraw(am int) {
	if pt.balance < am {
		fmt.Println("余额不足")
	} else {
		pt.balance = pt.balance - am
	}
}

